<template><article v-if="post" class="section"><div class="container article-container"><NuxtLink to="/actualites" class="text-link"><i class="pi pi-arrow-left"/> Toutes les actualités</NuxtLink><h1>{{post.title.rendered.replace(/<[^>]*>/g,'')}}</h1><div class="article-body" v-html="post.content.rendered"/></div></article></template>